def f(grid):
    if not grid: return 0
    R, C = len(grid), len(grid[0])
    seen = [[False]*C for _ in range(R)]
    count = 0
    def dfs(r, c):
        if 0 <= r < R and 0 <= c < C and grid[r][c] == '1' and not seen[r][c]:
            seen[r][c] = True
            dfs(r+1, c); dfs(r-1, c); dfs(r, c+1); dfs(r, c-1)
    for r in range(R):
        for c in range(C):
            if grid[r][c] == '1' and not seen[r][c]:
                count += 1; dfs(r, c)
    return count
```

